import re
def blocks(path):
    return re.findall(r"```\n(.*?)\n```", open(path).read(), re.S)
a = blocks('tmp/skill-writer/draft-held-sweep.md')
b = blocks('tmp/skill-writer/draft-held-push.md')
pairs = [
    ('.claude/skills/coordinator/SKILL.md', [(a[0], a[1])]),
    ('.claude/skills/coordinator/references/batch.md', [(b[0], b[1]), (b[2], b[3])]),
]
for p, rs in pairs:
    t = open(p).read()
    for o, n in rs:
        assert t.count(o) == 1, (p, o[:40])
        t = t.replace(o, n)
    open(p, 'w').write(t)
print("ok")

